#!/bin/sh
# Innioasis Y1 test BOOTIMG, variant "first" to "twenty-seventh" (docs/knowledge/y1-hardware.md,
# docs/planning/Y1-SECOND-BOOT-PLAN.md, Y1-THIRD-BOOT-PLAN.md, Y1-CHARGING-PLAN.md, Y1-POWER-PLAN.md, Y1-REBORN-PLAN.md, Y1-DATA-PLAN.md, Y1-MTP-PLAN.md, Y1-CHARGE-MODE-PLAN.md). Runs inside the locked build userspace:
#   python3 tools/build/run.py --output out/<fresh-dir> -- sh /project/tools/build/y1-boot.sh first
#   python3 tools/build/run.py --manifest kernel/patches-y1/manifest.json --output out/<fresh-dir> \
#       -- sh /project/tools/build/y1-boot.sh second   (or third to twenty-seventh)
# SPDX-License-Identifier: GPL-2.0-only
set -eu
variant=${1:?variant: first to twenty-seventh}
case $variant in
first) defines= ;;
second) defines=-DY1_SECOND_BOOT ;;
third) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT" ;;
fourth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT" ;;
fifth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT" ;;
sixth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT" ;;
seventh) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT" ;;
eighth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT" ;;
ninth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT" ;;
tenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT" ;;
eleventh) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT" ;;
twelfth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT" ;;
thirteenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT" ;;
fourteenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT" ;;
fifteenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT" ;;
sixteenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT" ;;
seventeenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT" ;;
eighteenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT" ;;
nineteenth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT" ;;
twentieth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT" ;;
twenty-first) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT -DY1_TWENTY_FIRST_BOOT" ;;
twenty-second) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT -DY1_TWENTY_FIRST_BOOT -DY1_TWENTY_SECOND_BOOT" ;;
twenty-third) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT -DY1_TWENTY_FIRST_BOOT -DY1_TWENTY_THIRD_BOOT" ;;
twenty-fourth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT -DY1_TWENTY_FIRST_BOOT -DY1_TWENTY_THIRD_BOOT -DY1_TWENTY_SECOND_BOOT" ;;
twenty-fifth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT -DY1_TWENTY_FIRST_BOOT -DY1_TWENTY_THIRD_BOOT -DY1_TWENTY_SECOND_BOOT -DY1_TWENTY_FIFTH_BOOT" ;;
twenty-sixth) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT -DY1_TWENTY_FIRST_BOOT -DY1_TWENTY_THIRD_BOOT -DY1_TWENTY_SECOND_BOOT" ;;
twenty-seventh) defines="-DY1_SECOND_BOOT -DY1_THIRD_BOOT -DY1_FOURTH_BOOT -DY1_FIFTH_BOOT -DY1_SIXTH_BOOT -DY1_SEVENTH_BOOT -DY1_EIGHTH_BOOT -DY1_NINTH_BOOT -DY1_TENTH_BOOT -DY1_ELEVENTH_BOOT -DY1_EIGHTEENTH_BOOT -DY1_NINETEENTH_BOOT -DY1_TWENTIETH_BOOT -DY1_TWENTY_FIRST_BOOT -DY1_TWENTY_THIRD_BOOT -DY1_TWENTY_SECOND_BOOT -DY1_TWENTY_FIFTH_BOOT" ;;
*) echo "unknown variant $variant" >&2; exit 2 ;;
esac
test ! -e /build/kernel || { echo 'a fresh output directory is required' >&2; exit 1; }
fragment=/project/kernel/config/y1-$variant-boot.config
make -C /src O=/build/kernel KCONFIG_ALLCONFIG="$fragment" allnoconfig
python3 /project/tools/build/check_config.py /build/kernel/.config "$fragment"
# shellcheck disable=SC2086 # $defines is empty or compiler flags without spaces inside
clang --target=arm-linux-gnueabi -mcpu=cortex-a7 -marm -mfloat-abi=soft $defines \
    -Os -fomit-frame-pointer -ffreestanding -fno-builtin -fno-stack-protector \
    -fno-unwind-tables -fno-asynchronous-unwind-tables -fno-pie -nostdlib -static \
    -fuse-ld=lld -Wl,--build-id=none,-e,_start,--gc-sections,-z,max-page-size=4096 \
    -Wall -Wextra -Werror /project/initramfs/start.S /project/initramfs/y1-init.c -o /build/y1-init
qemu-arm -cpu cortex-a7 /build/y1-init --selftest
make -C /src O=/build/kernel -j"$(nproc)" zImage
make -C /src O=/build/kernel scripts_dtc
clang -E -nostdinc -undef -D__DTS__ -x assembler-with-cpp -I /src/include \
    -I /src/arch/arm/boot/dts/mediatek "/project/kernel/dts/innioasis-y1-$variant-boot.dts" \
    -o /build/y1.preprocessed.dts
/build/kernel/scripts/dtc/dtc -I dts -O dtb -o /build/y1.dtb /build/y1.preprocessed.dts
cd /project
python3 -m tools.build.y1_boot "$variant" /build
cd /build
sha256sum "BOOTIMG-y1-$variant-boot.img" zImage-dtb y1.dtb y1-init kernel/.config > SHA256SUMS
cat SHA256SUMS
